@media (max-width: 768px) {
    .top-bar { flex-wrap: wrap; gap: 8px; padding: 10px; }
    .top-bar-left, .top-bar-right { flex-wrap: wrap; gap: 6px; min-width: 0; }
    .top-bar-left > *, .top-bar-right > * { flex-shrink: 1; min-width: 0; }
    .top-bar button, .top-bar select { font-size: 0.75rem; padding: 6px 10px; white-space: nowrap; }
    .content-area { padding: 0 12px; }
    .msg { max-width: 95%; }
    .command-block { margin: 10px 8px; }
    .command-block .cmd-preview { font-size: 0.75rem; }
    .command-block .act-btn { font-size: 0.7rem; padding: 6px 12px; }
}
